-- GETPROD → getProducts()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GETPROD',
    'SELECT
        PROD.PRODUCT_ID
        , PROD.PRODUCT_CODE
        , PROD.PRODUCT_CATEGORY_ID
        , CAT.PRODUCT_CATEGORY
        , PROD.PRODUCT_NAME
        , PROD.PRODUCT_NAME_INTERNAL
        , PROD.PRODUCT_DESCRIPTION
        , PROD.BRAND_ID
        , BRAND.BRAND
        , PROD.MIN_QUANTITY_SELL
        , PROD.LANGUAGE_CODE
        , PROD.PRODUCT_PRICE/10000 PRODUCT_PRICE
        , PROD.TAX_ID
        , PROD.CURRENCY_ID
        , PROD.UNIT_ID
        , DMD_UNIT.DES_UNIT
        , PROD.WEEKS_WARNING
        , PROD.QUANTITY_MIN_PRICE
        , PROD.QUANTITY_MAX_PRICE
        , PROD.TYPE_DAY_DELIVERY
        , DMD_DELIVERY_TYPE.DES_DELIVERY_TYPE
        , PROD.MIN_DAYS_DELIVERY
        , PROD.MAX_DAYS_DELIVERY
        , PROD.REMARK
        , PROD.DAYS_DELIVERY
        , PROD.PRODUCT_TYPE_ID
        , PROD.PROVIDER_ID
        , PERSONE.PERSONE_NAME
        , PROD.PARTNER_ID
        , PARTNER.PERSONE_NAME PARTNER_NAME
        , PROD.EFF_DATE
        , PROD.EXP_DATE
        , PROD.DAYS_EXP
        , PRODUCT_TYPE.BAN_EXPIRES
        , PRODUCT_TYPE.BAN_INVENTORY
        , PROD.SOURCE_ID
        , PROD.NUM_IMAGES
        , PROD.NUM_VIDEOS
    FROM
        KRC_PRODUCT PROD
        LEFT JOIN KRC_PRODUCT_CATEGORY CAT
        ON (CAT.PRODUCT_CATEGORY_ID = PROD.PRODUCT_CATEGORY_ID AND CAT.STATUS_ID = ''A'' )
        LEFT OUTER JOIN KRC_BRAND BRAND
        ON (BRAND.BRAND_ID = PROD.BRAND_ID AND BRAND.STATUS_ID = ''A'')
        LEFT OUTER JOIN KRC_TAX_TYPE TAX
        ON (TAX.TAX_ID = PROD.TAX_ID)
        LEFT OUTER JOIN DMD_UNIT
        ON (DMD_UNIT.CVE_UNIT = PROD.UNIT_ID)
        LEFT OUTER JOIN DMD_DELIVERY_TYPE
        ON (PROD.TYPE_DAY_DELIVERY = DMD_DELIVERY_TYPE.CVE_DELIVERY_TYPE)
        LEFT OUTER JOIN KRC_PRODUCT_TYPE PRODUCT_TYPE
        ON (PROD.PRODUCT_TYPE_ID = PRODUCT_TYPE.PRODUCT_TYPE_ID)
        LEFT OUTER JOIN KRC_PERSONE_IDENTITY PERSONE
        ON (PROD.PROVIDER_ID = PERSONE.PERSONE_ID AND PERSONE.STATUS_ID = ''A'')
        LEFT OUTER JOIN KRC_PERSONE_IDENTITY PARTNER
        ON (PROD.PARTNER_ID = PARTNER.PERSONE_ID AND PARTNER.STATUS_ID = ''A'')
    WHERE
        PROD.STATUS_ID = ''A'' and PROD.PRODUCT_ID <= 10
    ;',
    'Catálogo completo de productos (top 10)',
    'SELECT con todos los JOINs sobre KRC_PRODUCT, limitado a PRODUCT_ID <= 10',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Catálogo demo'
);

-- GTPRODAVL → queryGetProductsAvailable()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTPRODAVL',
    'SELECT PRODUCT_ID, PRODUCT_NAME, PRODUCT_DESCRIPTION, PRODUCT_TYPE, BRAND, NUM_IMAGES, NUM_VIDEOS, AVAIL, PRODUCT_PRICE, PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL, TAX_ID, TAX_APPLY, case when ID_UNIT = ''LT'' then ''Lt''    when ID_UNIT = ''UNI'' then ''Ud''    when ID_UNIT = ''KG'' then ''Kg''  end AS ID_UNIT, REMARK, MIN_QUANTITY_SELL FROM (select A.PRODUCT_ID, C.PRODUCT_NAME, C.PRODUCT_DESCRIPTION, D.PRODUCT_TYPE, C.BRAND, C.NUM_IMAGES, C.NUM_VIDEOS, ROUND(SUM(QUANTITY)) AVAIL, ROUND(max(PRODUCT_PRICE/10000), 2) PRODUCT_PRICE, E.PERSONE_ID, E.PERSONE_NAME, E.BUSINESS_NAME, E.EMAIL, C.TAX_ID, F.TAX_APPLY, TIP_UNIDAD.ID_UNIT, C.REMARK, C.MIN_QUANTITY_SELL , ROW_NUMBER() OVER (PARTITION BY C.PRODUCT_CATEGORY_ID, E.PERSONE_NAME ORDER BY IFNULL(C.MODIFY_DATE, C.CREATE_DATE) DESC) AS RN FROM (        SELECT PRODUCT_AVAIL_ID,ORDER_ID,PRODUCT_ID,QUANTITY,PRODUCT_PRICE,PRODUCT_PRICE_PAID,PREDICTABLE_FINISH_DATE,        RESET_MANUAL_DATE,CALIBRATE_DATE,CREATE_DATE,EXP_DATE,MODIFY_DATE,STATUS_DATE,USER_CREATE_ID,USER_MODIFY_ID,        METHOD,PRODUCT_CATEGORY_ID,PARTNER_ID,PARTNER_NAME         FROM KRC_PRODUCT_AVAIL     ) A INNER JOIN (  SELECT PRODUCT_ID, PRODUCT_NAME, PRODUCT_DESCRIPTION, PRODUCT_TYPE_ID, BRAND, REMARK, NUM_IMAGES, NUM_VIDEOS, PROVIDER_ID, TAX_ID, UNIT_ID, PRODUCT_CATEGORY_ID, IFNULL(MIN_QUANTITY_SELL, 1) AS MIN_QUANTITY_SELL, MODIFY_DATE, CREATE_DATE FROM KRC_PRODUCT WHERE STATUS_ID=''A'' GROUP BY PRODUCT_ID) C ON (A.PRODUCT_ID = C.PRODUCT_ID) LEFT OUTER JOIN (SELECT PRODUCT_TYPE_ID, PRODUCT_TYPE FROM KRC_PRODUCT_TYPE WHERE STATUS_ID = ''A'') D ON (C.PRODUCT_TYPE_ID = D.PRODUCT_TYPE_ID) LEFT OUTER JOIN (SELECT CVE_UNIT, ID_UNIT FROM DMD_UNIT) TIP_UNIDAD ON (C.UNIT_ID = TIP_UNIDAD.CVE_UNIT) LEFT OUTER JOIN (SELECT PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL FROM KRC_PERSONE_IDENTITY WHERE STATUS_ID = ''A'' AND PERSONE_TYPE = ''P'') E ON (C.PROVIDER_ID = E.PERSONE_ID) LEFT OUTER JOIN (SELECT TAX_ID, TAX_APPLY FROM KRC_TAX_TYPE) F ON (C.TAX_ID = F.TAX_ID)  WHERE A.QUANTITY>0 GROUP BY A.PRODUCT_ID, PRODUCT_NAME ORDER BY PRODUCT_NAME) AA WHERE AA.RN=1;',
    'Productos disponibles con stock',
    'SELECT productos disponibles agregando QUANTITY > 0 sobre KRC_PRODUCT_AVAIL',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Productos disponibles (genérico)'
);

-- GTPRODAVPT → queryGetProductsAvailableWithPartnerId()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTPRODAVPT',
    'SELECT PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME, PRODUCT_NAME_LONG, PRODUCT_DESCRIPTION, PRODUCT_TYPE, BRAND, NUM_IMAGES, NUM_VIDEOS, PRODUCT_PRICE, ROUND(PRODUCT_PRICE*(1+TAX_APPLY/100),2) TOTAL_BEFORE_DISCOUNT, ROUND(PRODUCT_PRICE_DISCOUNTED*(TAX_APPLY/100),2) TAX_AMOUNT, PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL, TAX_ID, TAX_APPLY, PRODUCT_PRICE_DISCOUNTED, ROUND(PRODUCT_PRICE_DISCOUNTED*(1+TAX_APPLY/100),2) TOTAL_AMOUNT , (PRODUCT_PRICE-PRODUCT_PRICE_DISCOUNTED) DISCOUNT_AMOUNT, case when ID_UNIT = ''LT'' then ''Lt''    when ID_UNIT = ''UNI'' then ''Ud''    when ID_UNIT = ''KG'' then ''Kg''  end AS ID_UNIT, REMARK, MIN_QUANTITY_SELL, PARTNER_ID, PARTNER_NAME, QUANTITY_MIN_PRICE, QUANTITY_MAX_PRICE, PRODUCT_CATEGORY_ID, RN FROM (select A.PRODUCT_ID, A.PRODUCT_CODE, A.PRODUCT_NAME, A.PRODUCT_DESCRIPTION, D.PRODUCT_TYPE, A.BRAND, A.NUM_IMAGES, A.NUM_VIDEOS, A.PRODUCT_PRICE PRODUCT_PRICE, A.PRODUCT_PRICE_FINAL PRODUCT_PRICE_DISCOUNTED, E.PERSONE_ID, E.PERSONE_NAME, E.BUSINESS_NAME, E.EMAIL, A.TAX_ID, F.TAX_APPLY, TIP_UNIDAD.ID_UNIT, A.REMARK, A.MIN_QUANTITY_SELL, A.PRODUCT_NAME_LONG, A.PARTNER_ID, A.PARTNER_NAME , A.MODIFY_DATE, A.CREATE_DATE , A.QUANTITY_MIN_PRICE,  A.QUANTITY_MAX_PRICE, A.PRODUCT_CATEGORY_ID, ROW_NUMBER() OVER (PARTITION BY A.PRODUCT_NAME, E.PERSONE_NAME ORDER BY A.PARTNER_ID DESC, IFNULL(A.MODIFY_DATE, A.CREATE_DATE) DESC, A.PRODUCT_PRICE_FINAL DESC, A.PRODUCT_ID DESC) AS RN FROM (        SELECT R.PRODUCT_ID, R.PRODUCT_CODE, R.PRODUCT_NAME_INTERNAL PRODUCT_NAME, R.PRODUCT_NAME PRODUCT_NAME_LONG, R.PRODUCT_DESCRIPTION, R.PRODUCT_TYPE_ID, R.BRAND, R.REMARK, R.NUM_IMAGES        , R.NUM_VIDEOS, R.PROVIDER_ID, R.TAX_ID, R.PRODUCT_PRICE , R.PRODUCT_PRICE_FINAL, R.PARTNER_ID, R.PARTNER_NAME         , R.UNIT_ID, R.PRODUCT_CATEGORY_ID, IFNULL(R.MIN_QUANTITY_SELL, 1) AS MIN_QUANTITY_SELL         , R.MODIFY_DATE, R.CREATE_DATE, R.QUANTITY_MIN_PRICE, R.QUANTITY_MAX_PRICE         FROM KRC_PRODUCT R         INNER JOIN (SELECT PRODUCT_TYPE_ID, PRODUCT_TYPE FROM KRC_PRODUCT_TYPE WHERE STATUS_ID = ''A'' AND PRODUCT_TYPE_CODE NOT IN (''ASCEN'',''COUMI'',''ENERG'',''SEGUR'',''PERSO'',''SEGUR'')) T         ON (R.PRODUCT_TYPE_ID = T.PRODUCT_TYPE_ID)        WHERE R.STATUS_ID=''A'' AND R.PRODUCT_CODE <> '''' AND R.PARTNER_ID IN (1, $1)   ) A LEFT OUTER JOIN (SELECT PRODUCT_TYPE_ID, PRODUCT_TYPE FROM KRC_PRODUCT_TYPE WHERE STATUS_ID = ''A'') D ON (A.PRODUCT_TYPE_ID = D.PRODUCT_TYPE_ID) LEFT OUTER JOIN (SELECT CVE_UNIT, ID_UNIT FROM DMD_UNIT) TIP_UNIDAD ON (A.UNIT_ID = TIP_UNIDAD.CVE_UNIT) LEFT OUTER JOIN (SELECT PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL FROM KRC_PERSONE_IDENTITY WHERE STATUS_ID = ''A'' AND PERSONE_TYPE = ''P'') E ON (A.PROVIDER_ID = E.PERSONE_ID) LEFT OUTER JOIN (SELECT TAX_ID, TAX_APPLY FROM KRC_TAX_TYPE) F ON (A.TAX_ID = F.TAX_ID) ORDER BY PRODUCT_NAME) AA WHERE (CASE WHEN $1 < 10000 THEN PARTNER_ID IN (1,$1) ELSE PARTNER_ID IN ($1) END ) ORDER BY PRODUCT_CATEGORY_ID, PERSONE_NAME, PARTNER_ID DESC, RN;',
    'Productos disponibles para partner',
    'SELECT productos disponibles filtrados por PARTNER_ID = $1 (partner 1 + partner del usuario)',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Listado tras login'
);

