    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTPRODAVNP',
    'SELECT PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME, PRODUCT_NAME_LONG, PRODUCT_DESCRIPTION, PRODUCT_TYPE, BRAND, NUM_IMAGES, NUM_VIDEOS, PRODUCT_PRICE, ROUND(PRODUCT_PRICE*(1+TAX_APPLY/100),2) TOTAL_BEFORE_DISCOUNT, ROUND(PRODUCT_PRICE_DISCOUNTED*(TAX_APPLY/100),2) TAX_AMOUNT, PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL, TAX_ID, TAX_APPLY, PRODUCT_PRICE_DISCOUNTED, ROUND(PRODUCT_PRICE_DISCOUNTED*(1+TAX_APPLY/100),2) TOTAL_AMOUNT , (PRODUCT_PRICE-PRODUCT_PRICE_DISCOUNTED) DISCOUNT_AMOUNT, case when ID_UNIT = ''LT'' then ''Lt''    when ID_UNIT = ''UNI'' then ''Ud''    when ID_UNIT = ''KG'' then ''Kg''  end AS ID_UNIT, REMARK, MIN_QUANTITY_SELL, PARTNER_ID, PARTNER_NAME, QUANTITY_MIN_PRICE, QUANTITY_MAX_PRICE, PRODUCT_CATEGORY_ID, RN FROM (select A.PRODUCT_ID, A.PRODUCT_CODE, A.PRODUCT_NAME, A.PRODUCT_DESCRIPTION, D.PRODUCT_TYPE, A.BRAND, A.NUM_IMAGES, A.NUM_VIDEOS, A.PRODUCT_PRICE PRODUCT_PRICE, A.PRODUCT_PRICE_FINAL PRODUCT_PRICE_DISCOUNTED, E.PERSONE_ID, E.PERSONE_NAME, E.BUSINESS_NAME, E.EMAIL, A.TAX_ID, F.TAX_APPLY, TIP_UNIDAD.ID_UNIT, A.REMARK, A.MIN_QUANTITY_SELL, A.PRODUCT_NAME_LONG, A.PARTNER_ID, A.PARTNER_NAME , A.MODIFY_DATE, A.CREATE_DATE , A.QUANTITY_MIN_PRICE,  A.QUANTITY_MAX_PRICE, A.PRODUCT_CATEGORY_ID, ROW_NUMBER() OVER (PARTITION BY A.PRODUCT_NAME, E.PERSONE_NAME ORDER BY A.PARTNER_ID DESC, IFNULL(A.MODIFY_DATE, A.CREATE_DATE) DESC, A.PRODUCT_PRICE_FINAL DESC, A.PRODUCT_ID DESC) AS RN FROM (        SELECT PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME_INTERNAL PRODUCT_NAME, PRODUCT_NAME PRODUCT_NAME_LONG, PRODUCT_DESCRIPTION, PRODUCT_TYPE_ID, BRAND, REMARK, NUM_IMAGES        , NUM_VIDEOS, PROVIDER_ID, TAX_ID, PRODUCT_PRICE , PRODUCT_PRICE_FINAL, PARTNER_ID, PARTNER_NAME        , UNIT_ID, PRODUCT_CATEGORY_ID, IFNULL(MIN_QUANTITY_SELL, 1) AS MIN_QUANTITY_SELL        , MODIFY_DATE, CREATE_DATE, QUANTITY_MIN_PRICE, QUANTITY_MAX_PRICE        FROM KRC_PRODUCT        WHERE STATUS_ID=''A'' AND PARTNER_ID = 1   ) A LEFT OUTER JOIN (SELECT PRODUCT_TYPE_ID, PRODUCT_TYPE FROM KRC_PRODUCT_TYPE WHERE STATUS_ID = ''A'' AND PRODUCT_TYPE_CODE NOT IN (''ASCEN'',''COUMI'',''ENERG'',''SEGUR'',''PERSO'',''SEGUR'')) D ON (A.PRODUCT_TYPE_ID = D.PRODUCT_TYPE_ID) LEFT OUTER JOIN (SELECT CVE_UNIT, ID_UNIT FROM DMD_UNIT) TIP_UNIDAD ON (A.UNIT_ID = TIP_UNIDAD.CVE_UNIT) LEFT OUTER JOIN (SELECT PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL FROM KRC_PERSONE_IDENTITY WHERE STATUS_ID = ''A'' AND PERSONE_TYPE = ''P'') E ON (A.PROVIDER_ID = E.PERSONE_ID) LEFT OUTER JOIN (SELECT TAX_ID, TAX_APPLY FROM KRC_TAX_TYPE) F ON (A.TAX_ID = F.TAX_ID) ORDER BY PRODUCT_NAME) AA ORDER BY PRODUCT_CATEGORY_ID, PERSONE_NAME, PARTNER_ID DESC, RN;',
    'Productos disponibles sin login',
    'SELECT productos disponibles del partner por defecto (PARTNER_ID = 1)',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Listado sin login'
);

-- GTPRODAVPR → getProductAvailWithProductId()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTPRODAVPR',
    'SELECT PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME, PRODUCT_NAME_LONG, PRODUCT_DESCRIPTION, PRODUCT_TYPE, BRAND, NUM_IMAGES, NUM_VIDEOS, PRODUCT_PRICE, ROUND(PRODUCT_PRICE*(1+TAX_APPLY/100),2) TOTAL_BEFORE_DISCOUNT, ROUND(PRODUCT_PRICE_DISCOUNTED*(TAX_APPLY/100),2) TAX_AMOUNT, PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL, TAX_ID, TAX_APPLY, PRODUCT_PRICE_DISCOUNTED, ROUND(PRODUCT_PRICE_DISCOUNTED*(1+TAX_APPLY/100),2) TOTAL_AMOUNT , (PRODUCT_PRICE-PRODUCT_PRICE_DISCOUNTED) DISCOUNT_AMOUNT, case when ID_UNIT = ''LT'' then ''Lt''    when ID_UNIT = ''UNI'' then ''Ud''    when ID_UNIT = ''KG'' then ''Kg''  end AS ID_UNIT, REMARK, MIN_QUANTITY_SELL, PARTNER_ID, PARTNER_NAME, QUANTITY_MIN_PRICE, QUANTITY_MAX_PRICE, PRODUCT_CATEGORY_ID, RN FROM (select A.PRODUCT_ID, A.PRODUCT_CODE, A.PRODUCT_NAME, A.PRODUCT_DESCRIPTION, D.PRODUCT_TYPE, A.BRAND, A.NUM_IMAGES, A.NUM_VIDEOS, A.PRODUCT_PRICE PRODUCT_PRICE, A.PRODUCT_PRICE_FINAL PRODUCT_PRICE_DISCOUNTED, E.PERSONE_ID, E.PERSONE_NAME, E.BUSINESS_NAME, E.EMAIL, A.TAX_ID, F.TAX_APPLY, TIP_UNIDAD.ID_UNIT, A.REMARK, A.MIN_QUANTITY_SELL, A.PRODUCT_NAME_LONG, A.PARTNER_ID, A.PARTNER_NAME , A.MODIFY_DATE, A.CREATE_DATE , A.QUANTITY_MIN_PRICE,  A.QUANTITY_MAX_PRICE, A.PRODUCT_CATEGORY_ID, ROW_NUMBER() OVER (PARTITION BY A.PRODUCT_CATEGORY_ID, E.PERSONE_NAME ORDER BY A.PARTNER_ID DESC, IFNULL(A.MODIFY_DATE, A.CREATE_DATE) DESC, A.PRODUCT_PRICE_FINAL DESC, A.PRODUCT_ID DESC) AS RN FROM (        SELECT PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME_INTERNAL PRODUCT_NAME, PRODUCT_NAME PRODUCT_NAME_LONG, PRODUCT_DESCRIPTION, PRODUCT_TYPE_ID, BRAND, REMARK, NUM_IMAGES        , NUM_VIDEOS, PROVIDER_ID, TAX_ID, PRODUCT_PRICE , PRODUCT_PRICE_FINAL, PARTNER_ID, PARTNER_NAME        , UNIT_ID, PRODUCT_CATEGORY_ID, IFNULL(MIN_QUANTITY_SELL, 1) AS MIN_QUANTITY_SELL         , MODIFY_DATE, CREATE_DATE, QUANTITY_MIN_PRICE, QUANTITY_MAX_PRICE        FROM KRC_PRODUCT        WHERE STATUS_ID=''A'' AND PRODUCT_ID = $1   ) A LEFT OUTER JOIN (SELECT PRODUCT_TYPE_ID, PRODUCT_TYPE FROM KRC_PRODUCT_TYPE WHERE STATUS_ID = ''A'') D ON (A.PRODUCT_TYPE_ID = D.PRODUCT_TYPE_ID) LEFT OUTER JOIN (SELECT CVE_UNIT, ID_UNIT FROM DMD_UNIT) TIP_UNIDAD ON (A.UNIT_ID = TIP_UNIDAD.CVE_UNIT) LEFT OUTER JOIN (SELECT PERSONE_ID, PERSONE_NAME, BUSINESS_NAME, EMAIL FROM KRC_PERSONE_IDENTITY WHERE STATUS_ID = ''A'' AND PERSONE_TYPE = ''P'') E ON (A.PROVIDER_ID = E.PERSONE_ID) LEFT OUTER JOIN (SELECT TAX_ID, TAX_APPLY FROM KRC_TAX_TYPE) F ON (A.TAX_ID = F.TAX_ID) ORDER BY PRODUCT_NAME) AA ORDER BY PRODUCT_CATEGORY_ID, PERSONE_NAME, PARTNER_ID DESC, RN;',
    'Detalle de producto disponible',
    'SELECT producto disponible filtrado por PRODUCT_ID = $1',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Detalle de producto'
