-- GTPRCHUSR → queryGetPurchaseByUserId()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTPRCHUSR',
    'SELECT ORDER_ID, PROVIDER_NAME, BUYER_NAME, SHOW_NAME, CASE WHEN COUNT(DISTINCT STATUS_NAME)=1 THEN max(STATUS_NAME)    ELSE ''VARIOS'' END ALL_STATUS, CASE WHEN COUNT(DISTINCT STATUS_ID)=1 THEN max(STATUS_ID)    ELSE ''VARIOS'' END STATUS_ID, COUNT(DISTINCT STATUS_NAME) NUM_STATUS, NVL(SUM(CASE WHEN NEW_QUANTITY IS NULL THEN QUANTITY ELSE NEW_QUANTITY END), 0) ITEMS, MAX(SITUACION) SITUACION, NVL(SUM(TOTAL_AMOUNT), 0) TOTAL_AMOUNT, NVL(SUM(TAX_AMOUNT), 0) TAX_AMOUNT, NVL(SUM(DISCOUNT_AMOUNT), 0) DISCOUNT_AMOUNT, NVL(SUM(PRODUCT_PRICE_FINAL), 0) PRODUCT_PRICE_FINAL , NVL(SUM(PRODUCT_PRICE), 0) PRODUCT_PRICE , NVL(SUM(TOTAL_BEFORE_DISCOUNT_WITHOUT_TAX), 0) TOTAL_BEFORE_DISCOUNT_WITHOUT_TAX , NVL(SUM(TOTAL_AFTER_DISCOUNT_WITHOUT_TAX), 0) TOTAL_AFTER_DISCOUNT_WITHOUT_TAX, MAX(ORDER_DATE) ORDER_DATE FROM (    SELECT ORDER_ID, A.PRODUCT_NAME, A.PRODUCT_ID, A.PROVIDER_NAME    , CASE WHEN D.PARTNER_ID=1 AND J.PERSONE_TYPE=''P'' THEN J.PERSONE_NAME           ELSE D.PARTNER_NAME END BUYER_NAME    , CASE WHEN D.PARTNER_ID=1 AND J.PERSONE_TYPE=''P'' THEN J.PERSONE_NAME           WHEN J.PERSONE_TYPE = ''P'' THEN D.PARTNER_NAME           ELSE A.PROVIDER_NAME END SHOW_NAME    , CASE WHEN A.STATUS_ID IN (''E'',''F'',''P'',''S'',''O'',''D'') THEN ''ABIERTO''        ELSE ''CERRADO'' END SITUACION    , A.TOTAL_AMOUNT    , A.TAX_AMOUNT    , A.DISCOUNT_AMOUNT    , (A.PRODUCT_PRICE - (A.DISCOUNT_AMOUNT/A.QUANTITY)) PRODUCT_PRICE_FINAL    , A.QUANTITY, A.NEW_QUANTITY, B.TAX_APPLY, C.STATUS_ID, C.STATUS_NAME, A.PRODUCT_PRICE     , (A.QUANTITY * A.PRODUCT_PRICE) TOTAL_BEFORE_DISCOUNT_WITHOUT_TAX     , ((A.QUANTITY * A.PRODUCT_PRICE) + A.DISCOUNT_AMOUNT) TOTAL_AFTER_DISCOUNT_WITHOUT_TAX, A.ORDER_DATE    FROM KRC_PURCHASE A, KRC_TAX_TYPE B,          (SELECT STATUS_OBJECT_ID STATUS_ID, STATUS_NAME FROM KRC_STATUS GROUP BY STATUS_OBJECT_ID, STATUS_NAME) C          ,KRC_PRODUCT D, KRC_PERSONE_IDENTITY E, KRC_PERSONE_IDENTITY H          , (SELECT * FROM (SELECT PERSONE_ID, PERSONE_TYPE, PERSONE_NAME, USER_ID, PARTNER_NAME, PARTNER_ID             , ROW_NUMBER() OVER (PARTITION BY USER_ID ORDER BY PERSONE_ID)  AS RN  FROM KRC_PERSONE_IDENTITY  ) BB WHERE RN=1) J    WHERE       (A.ORDER_DATE >= DATE_ADD(CURRENT_DATE(), interval -2 MONTH) OR A.STATUS_ID IN (''E'',''F'',''P'',''S'',''O'',''D''))      AND A.TAX_ID=B.TAX_ID AND A.STATUS_ID=C.STATUS_ID AND A.USER_CREATE_ID = E.USER_ID      AND A.PRODUCT_ID=D.PRODUCT_ID AND D.PROVIDER_ID = H.PERSONE_ID      AND $1 = J.USER_ID      AND (A.USER_CREATE_ID = $1         OR $1 IN (SELECT I.USER_ID                     FROM KRC_PERSONE_IDENTITY I WHERE I.STATUS_ID = ''A'' AND I.PARTNER_ID = E.PARTNER_ID                    GROUP BY I.USER_ID                 )        OR $1 IN (SELECT F.USER_ID                    FROM KRC_PERSONE_IDENTITY F, KRR_USER_ROLE G                    WHERE F.STATUS_ID = ''A'' AND F.USER_ID=G.USER_ID AND G.ROLE_ID=2 AND NVL(F.PARTNER_ID,1) != 1                    AND F.PARTNER_ID = H.PARTNER_ID                    GROUP BY F.USER_ID                 )        )    ) AA GROUP BY ORDER_ID, PROVIDER_NAME, BUYER_NAME, SHOW_NAME;',
    'Compras del usuario',
    'Lista compras del usuario o las que pueda ver según PARTNER_ID/ROLE',
    'A',
