-- GTDFLOGAD → getDefaultLogisticAddress()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
    CREATE_DATE, EFF_DATE, EXP_DATE, MODIFY_DATE, STATUS_DATE,
    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTDFLOGAD',
    'SELECT
    ADDR.ADDR_ID
    , ADDR.ADDR_STREET
    , ADDR.ADDR_NUMBER
    , ADDR.ADDR_COMPLEMENT
    , ADDR.SUBURB
    , ADDR.DISTRICT
    , ADDR.CITY
    , ADDR.PROVINCE
    , ADDR.STATE
    , ADDR.COUNTRY
    , ADDR.ADDR_ZIP_CODE
    , ADDR.INDICATION
    , ADDR.STATUS_ID
    FROM KRC_ADDRESS ADDR
    INNER JOIN KRC_PERSONE_IDENTITY PER
    ON (ADDR.ADDR_OBJECT = PER.PERSONE_ID AND ADDR.ADDR_TYPE = ''L'' AND ADDR.STATUS_ID = ''D'')
    INNER JOIN  KRC_USER USER
    ON (PER.USER_ID = USER.USER_ID)
    WHERE USER.USER_ID = $1;',
    'Dirección logística por defecto del usuario',
    'SELECT KRC_ADDRESS con ADDR_TYPE=L y STATUS_ID=D (default)',
    'A',
    NOW(), CURRENT_DATE(), NULL, NULL, CURRENT_DATE(),
    1, NULL, 'K', 0, 'APP', 'Pantalla de dirección'
);

-- GTROLEUSR → getRoleByUser()
INSERT INTO KRC_QUERY (
    QUERY_CODE, QUERY, NAME, DESCRIPTION, STATUS_ID,
