    USER_CREATE_ID, USER_MODIFY_ID, SCENARIO, PARTNER_ID, UNIT, FUNCTIONALITY
) VALUES (
    'GTROLEUSR',
    'SELECT C.ROLE_NAME ROLE_NAME FROM KRC_USER A, KRR_USER_ROLE B, KRC_ROLE C WHERE A.USER_ID = B.USER_ID AND B.ROLE_ID = C.ROLE_ID AND A.USER_ID = $1;',
    'Rol del usuario',
